 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    comp_of = [[-1] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            idx = len(components)
            for y, x in cells:
                comp_of[y][x] = idx
            components.append(cells)

    # A large, solid rectangle identifies the object; recolor its entire
    # connected same-color component, including any attached protrusions.
    target_components = set()
    for top in range(h):
        for bottom in range(top + 4, h):
            for left in range(w):
                color = grid[top][left]
                right = left
                while right < w and all(grid[r][right] == color for r in range(top, bottom + 1)):
                    right += 1
                if right - left >= 5:
                    target_components.add(comp_of[top][left])

    out = [row[:] for row in grid]
    for idx in target_components:
        for r, c in components[idx]:
            out[r][c] = 4
    return out


